function validate([word1, word2]) {
  if (word1.length < 1 || word1.length > 100) return 'word1 needs 1 to 100 letters.';
  if (word2.length !== word1.length) return 'word1 and word2 must have the same length.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Use lowercase English letters only.';
  return null;
}

reference:
function checkAlmostEquivalent(word1, word2) {
  const diff = new Array(26).fill(0);

  for (const ch of word1) {
    diff[ch.charCodeAt(0) - 97]++;
  }
  for (const ch of word2) {
    diff[ch.charCodeAt(0) - 97]--;
  }

  for (const d of diff) {
    if (Math.abs(d) > 3) {
      return false;
    }
  }
  return true;
}

