function checkAlmostEquivalent(word1, word2) {
  const count = (word, letter) => word.split('').filter(ch => ch === letter).length;
  return 'abcdefghijklmnopqrstuvwxyz'.split('').every(letter => Math.abs(count(word1, letter) - count(word2, letter)) <= 3);
}

