function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 12);
  const span = 1 + Math.floor(rand() * (size === 'large' ? 26 : 5));
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * span));
  const word1 = Array.from({ length: n }, letter);
  let word2;
  if (rand() < 0.5) {
    // A shuffled copy with a few letters replaced, so the answer is often true.
    word2 = word1.slice();
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [word2[i], word2[j]] = [word2[j], word2[i]];
    }
    const changes = Math.floor(rand() * 7);
    for (let k = 0; k < changes; k++) word2[Math.floor(rand() * n)] = letter();
  } else {
    word2 = Array.from({ length: n }, letter);
  }
  return [word1.join(''), word2.join('')];
}
